// lowerCloud reports whether candidate has lower cloud cover than current
// (missing cloud sorts last).
func lowerCloud(candidate, current timelineEntry) bool {
	if candidate.CloudCover == nil {
		return false
	}
	if current.CloudCover == nil {
		return true
	}
	return *candidate.CloudCover < *current.CloudCover
}
